div.t-attf-style:
height:100%; border-radius:999px;
width:#{record.record_usage_percent.raw_value or 0}%;
background:#{
    record.storage_warning.raw_value ? '#f59e0b' :
    (record.record_usage_percent.raw_value or 0) > 60 ? '#3b82f6' : '#10b981'
};
transition: width 0.3s ease;
